spec.expr:
sum(rate(zeebe_executed_instances_total{action="completed", namespace=~"(c8-)?release-8.*", type="ROOT_PROCESS_INSTANCE"}[1d])) by (namespace)
    /
(sum(rate(grpc_server_processing_duration_seconds_count{namespace=~"(c8-)?release-8.*", method="CreateProcessInstance"}[1d])) by (namespace)
or
sum(rate(http_server_requests_seconds_count{
    method="POST",
   namespace=~"(c8-)?release-8.*",
    uri="/v2/process-instances",
  }[1d]) != 0) by (namespace)
)
